        Title="마스크 키프레임 · "+ProductInfo.Credit;Width=1210;Height=850;MinWidth=900;MinHeight=650;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=new SolidColorBrush(Color.FromRgb(18,29,42));Foreground=Brushes.White;
        _source=SourceImage.Read(path)??throw new InvalidDataException("원본을 읽지 못했습니다.");_mask=mask.Copy(false);Result=mask.Motion?.Copy()??new MotionDefinition{LengthFrames=Math.Clamp((int)Math.Round(mask.Duration*30),1,9000)};Preview=new(_source,_mask);
        var root=new DockPanel{Margin=new Thickness(12)};Content=root;var bottom=new DockPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);var credit=new TextBlock{Text=ProductInfo.Credit,Margin=new Thickness(12,0,0,0)};DockPanel.SetDock(credit,Dock.Right);bottom.Children.Add(credit);bottom.Children.Add(_info);
        var tools=new WrapPanel();DockPanel.SetDock(tools,Dock.Top);root.Children.Add(tools);Button(tools,"재생 / 정지",()=>{_playing=!_playing;_clock.Restart();});Button(tools,"처음",()=>SetFrame(0));Button(tools,"−1f",()=>SetFrame(_cursor-1));Button(tools,"＋1f",()=>SetFrame(_cursor+1));Button(tools,"복사",CopyKeys);Button(tools,"붙여넣기",PasteKeys);Button(tools,"되돌리기",Undo);Button(tools,"다시",Redo);Button(tools,"적용",()=>{Result.Validate();DialogResult=true;});var cancel=Button(tools,"취소",Close);cancel.IsCancel=true;
        var body=new Grid();body.ColumnDefinitions.Add(new());body.ColumnDefinitions.Add(new(){Width=new GridLength(250)});body.RowDefinitions.Add(new());body.RowDefinitions.Add(new(){Height=new GridLength(34)});body.RowDefinitions.Add(new(){Height=new GridLength(310)});root.Children.Add(body);var previewPanel=new DockPanel();body.Children.Add(previewPanel);var viewTools=new WrapPanel();DockPanel.SetDock(viewTools,Dock.Top);previewPanel.Children.Add(viewTools);Button(viewTools,"−",()=>Preview.ZoomAt(.8));Button(viewTools,"＋",()=>Preview.ZoomAt(1.25));Button(viewTools,"100%",Preview.Native);Button(viewTools,"화면 맞춤",Preview.Fit);var zoomLabel=new TextBlock{Margin=new Thickness(5),Foreground=Brushes.LightGreen};viewTools.Children.Add(zoomLabel);Preview.ViewChanged+=()=>zoomLabel.Text=$"{Preview.Viewport.Scale*100:0}%";var anchorTool=new CheckBox{Content="기준점 이동"};viewTools.Children.Add(anchorTool);anchorTool.Checked+=(_,_)=>Preview.AnchorTool=true;anchorTool.Unchecked+=(_,_)=>Preview.AnchorTool=false;previewPanel.Children.Add(Preview);
