        Label(fields,"속성");foreach(var p in Enum.GetValues<MotionProperty>())_property.Items.Add(MotionDefinition.Name(p));fields.Children.Add(_property);Label(fields,"프레임");fields.Children.Add(_frame);Label(fields,"값 · 위치/크기/불투명도/기준점 %, 회전 °");fields.Children.Add(_value);Label(fields,"다음 키까지 움직임");foreach(var text in EditorTerms.Easing)_easing.Items.Add(text);fields.Children.Add(_easing);Button(fields,"키 추가 / 수정",ApplyKey);Button(fields,"선택 키 삭제",DeleteKeys);Button(fields,"− 눈금",()=>Timeline.Zoom(.8));Button(fields,"＋ 눈금",()=>Timeline.Zoom(1.25));
        PropertyMouse=MouseValueControl.Attach(_value,-2000,2000,"%",v=>{if(!_loading)SetKey(Timeline.SelectedProperty,_cursor,v/(Timeline.SelectedProperty==MotionProperty.Rotation?1:100),(KeyEasing)Math.Max(0,_easing.SelectedIndex));},BeginPropertyGesture,EndPropertyGesture);
        LengthMouse=MouseValueControl.Attach(_length,1,9000,"f",v=>{if(_loading)return;var copy=Result.Copy();var length=Math.Clamp((int)Math.Round(v),1,copy.Fps*300);var ratio=(double)length/copy.LengthFrames;foreach(var track in copy.Tracks){foreach(var key in track.Keys)key.Frame=(int)Math.Round(key.Frame*ratio);track.Keys=track.Keys.GroupBy(k=>k.Frame).Select(g=>g.Last()).ToList();}copy.LengthFrames=length;_cursor=Math.Clamp((int)Math.Round(_cursor*ratio),0,length);Result=copy;Record();Refresh();},BeginPropertyGesture,EndPropertyGesture);
        Preview.GestureStarted+=BeginPropertyGesture;Preview.GestureEnded+=EndPropertyGesture;Preview.ValuesEdited+=values=>{foreach(var item in values)Result.SetKey(item.Key,_cursor,item.Value);var property=values.ContainsKey(MotionProperty.AnchorX)?MotionProperty.AnchorX:values.ContainsKey(MotionProperty.Rotation)?MotionProperty.Rotation:values.ContainsKey(MotionProperty.ScaleX)?MotionProperty.ScaleX:MotionProperty.X;Timeline.SelectedProperty=property;var prior=_loading;_loading=true;_property.SelectedIndex=(int)property;_loading=prior;Timeline.SelectedKeys.Clear();LoadKey();UpdatePreview();};
        var only=new CheckBox{Content="마스크만 보기"};fields.Children.Add(only);only.Checked+=(_,_)=>{Preview.MaskOnly=true;UpdatePreview();};only.Unchecked+=(_,_)=>{Preview.MaskOnly=false;UpdatePreview();};
        _property.SelectionChanged+=(_,_)=>{if(!_loading){Timeline.SelectedProperty=(MotionProperty)Math.Max(0,_property.SelectedIndex);Timeline.SelectedKeys.Clear();LoadKey();}};Timeline.SelectionChanged+=()=>{_loading=true;_property.SelectedIndex=(int)Timeline.SelectedProperty;_loading=false;LoadKey();};Timeline.Seeked+=frame=>SetFrame(frame,true,false);Timeline.AddRequested+=(p,f)=>SetKey(p,f,Result.Value(p,f),KeyEasing.EaseInOut);Timeline.DeleteRequested+=DeleteKeys;Timeline.Edited+=()=>{LoadKey();UpdatePreview();};Timeline.GestureStarted+=()=>{Record();_gesture=JsonSerializer.Serialize(Result);};Timeline.GestureEnded+=commit=>{if(!commit&&_gesture is not null)Result=JsonSerializer.Deserialize<MotionDefinition>(_gesture)!;_gesture=null;Record();Refresh();};
        _scrub.ValueChanged+=(_,_)=>{if(!_loading)SetFrame((int)_scrub.Value);};PreviewKeyDown+=(_,e)=>{if(MainWindow.IsTextEditing(Keyboard.FocusedElement as DependencyObject))return;if(Keyboard.Modifiers==ModifierKeys.Control){if(e.Key==Key.C)CopyKeys();else if(e.Key==Key.V)PasteKeys();else if(e.Key==Key.Z)Undo();else if(e.Key==Key.Y)Redo();else return;e.Handled=true;}else if(Keyboard.Modifiers==(ModifierKeys.Control|ModifierKeys.Shift)&&e.Key==Key.Z){Redo();e.Handled=true;}};
        _timer.Tick+=(_,_)=>{if(_playing)SetFrame((int)(_clock.Elapsed.TotalSeconds*Result.Fps)%(Result.LengthFrames+1),false);};_timer.Start();Closed+=(_,_)=>{_timer.Stop();Preview.Dispose();_source.Dispose();};Refresh();_history.Reset(State());
    }
    private static Button Button(Panel host,string text,Action action){var b=new Button{Content=text,Padding=new Thickness(7,5,7,5)};b.Click+=(_,_)=>action();host.Children.Add(b);return b;}
    private static void Label(Panel host,string text)=>host.Children.Add(new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(3,8,3,4)});
    private EditorState State()=>new(JsonSerializer.Serialize(Result),null,null,null,_cursor);
    private void Record(){if(_gesture is null)_history.Record(State());}
    private void Restore(EditorState? state){if(state is null)return;Result=JsonSerializer.Deserialize<MotionDefinition>(state.Json)!;_cursor=(int)state.Time;Refresh();}
    public void Undo(){_playing=false;Restore(_history.Undo());}public void Redo(){_playing=false;Restore(_history.Redo());}
    public void SetFrame(int frame,bool stop=true,bool clearSelection=true){if(stop)_playing=false;_cursor=Math.Clamp(frame,0,Result.LengthFrames);Timeline.CursorFrame=_cursor;if(clearSelection)Timeline.SelectedKeys.Clear();LoadKey();UpdatePreview();}
    private void Refresh(){_loading=true;Timeline.Motion=Result;Timeline.CursorFrame=_cursor;Timeline.Refresh();_fps.Text=Result.Fps.ToString();_length.Text=Result.LengthFrames.ToString();_scrub.Maximum=Result.LengthFrames;_property.SelectedIndex=(int)Timeline.SelectedProperty;_loading=false;LoadKey();UpdatePreview();}
    private void LoadKey(){_loading=true;var key=Result.Tracks.SelectMany(t=>t.Keys).FirstOrDefault(k=>Timeline.SelectedKeys.Contains(k.Id));var p=Timeline.SelectedProperty;_frame.Text=(key?.Frame??_cursor).ToString();PropertyMouse?.Configure(p==MotionProperty.Rotation?-360:MotionDefinition.IsUnit(p)?0:p is MotionProperty.ScaleX or MotionProperty.ScaleY?1:-2000,p==MotionProperty.Rotation?360:MotionDefinition.IsUnit(p)?100:2000,p==MotionProperty.Rotation?"°":"%");_value.Text=((key?.Value??Result.Value(p,_cursor))*(p==MotionProperty.Rotation?1:100)).ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);_easing.SelectedIndex=(int)(key?.Easing??KeyEasing.EaseInOut);_loading=false;}
    private void UpdatePreview(){_loading=true;_scrub.Value=_cursor;_loading=false;Timeline.InvalidateVisual();_mask.Motion=Result;Preview.Time=_mask.Start+_mask.Duration*_cursor/Result.LengthFrames;Preview.InvalidateVisual();_info.Text=$"{_cursor}f / {Result.LengthFrames}f · {_mask.Duration*_cursor/Result.LengthFrames:0.###}초";}
    public void SetKey(MotionProperty property,int frame,double value,KeyEasing easing=KeyEasing.EaseInOut){Record();Result.SetKey(property,frame,value,easing);_cursor=Math.Clamp(frame,0,Result.LengthFrames);Timeline.SelectedProperty=property;Record();Refresh();}
    private void BeginPropertyGesture(){_playing=false;Record();_gesture=JsonSerializer.Serialize(Result);}
    private void EndPropertyGesture(bool commit){if(!commit&&_gesture is not null)Result=JsonSerializer.Deserialize<MotionDefinition>(_gesture)!;_gesture=null;Record();Refresh();}
    private void ApplyKey(){try{var p=(MotionProperty)Math.Max(0,_property.SelectedIndex);var frame=int.Parse(_frame.Text);var value=double.Parse(_value.Text,System.Globalization.CultureInfo.InvariantCulture)/(p==MotionProperty.Rotation?1:100);SetKey(p,frame,value,(KeyEasing)Math.Max(0,_easing.SelectedIndex));}catch(Exception ex){_info.Text=ex.Message;}}
    private void ApplyTiming(){try{Record();var fps=int.Parse(_fps.Text);var length=int.Parse(_length.Text);var copy=Result.Copy();copy.ChangeFps(fps,false);copy.LengthFrames=length;copy.Validate();Result=copy;_cursor=Math.Min(_cursor,length);Record();Refresh();}catch(Exception ex){_info.Text=ex.Message;}}
    private void DeleteKeys(){Record();foreach(var track in Result.Tracks)track.Keys.RemoveAll(k=>Timeline.SelectedKeys.Contains(k.Id));Timeline.SelectedKeys.Clear();Record();Refresh();}
    public void CopyKeys(){_clipboard=Result.Tracks.SelectMany(t=>t.Keys.Where(k=>Timeline.SelectedKeys.Contains(k.Id)||k.Frame==_cursor&&t.Property==Timeline.SelectedProperty).Select(k=>(t.Property,k with{}))).ToList();}
    public void PasteKeys(){if(_clipboard.Count==0)return;Record();var first=_clipboard.Min(x=>x.Key.Frame);foreach(var item in _clipboard)Result.SetKey(item.Property,Math.Clamp(_cursor+item.Key.Frame-first,0,Result.LengthFrames),item.Key.Value,item.Key.Easing);Record();Refresh();}
